import Gopuram from "./Gopuram";
import styles from "./Hero.module.css";

const STAR_COUNT = 46;

// Deterministic pseudo-random star field so server and client render match.
function seededStars(count) {
  let seed = 7;
  const rand = () => {
    seed = (seed * 9301 + 49297) % 233280;
    return seed / 233280;
  };
  return Array.from({ length: count }).map((_, i) => ({
    id: i,
    top: rand() * 62,
    left: rand() * 100,
    size: 1 + rand() * 1.8,
    delay: rand() * 6,
  }));
}

export default function Hero() {
  const stars = seededStars(STAR_COUNT);

  return (
    <header className={styles.hero}>
      <div className={styles.sky}>
        {stars.map((s) => (
          <span
            key={s.id}
            className={styles.star}
            style={{
              top: `${s.top}%`,
              left: `${s.left}%`,
              width: `${s.size}px`,
              height: `${s.size}px`,
              animationDelay: `${s.delay}s`,
            }}
          />
        ))}
      </div>

      <div className={`${styles.content} wrap`}>
        <p className={`eyebrow ${styles.eyebrow}`}>Together with their families</p>

        <p className={styles.names}>
          Sai Swetha <span className={styles.amp}>&amp;</span> Sai Santhosh
        </p>

        <div className={styles.divider} />

        <p className={styles.dateLine}>Saturday, 4th September 2026</p>

        <div className={styles.muhurtham}>
          <span className={styles.muhurthamDot} />
          Muhurtham at 3:50 AM
        </div>

        <a href="#hashtag" className={styles.hashtagPill}>
          #SaiSwethaWedsSaiSanthosh
        </a>
      </div>

      <Gopuram className={styles.gopuram} />
    </header>
  );
}
